// Minimal publication helper (no opencode code): maps source exports and nested imports conditions to dist.
type Manifest = { exports: Record<string, string | null>; imports?: Record<string, Record<string, string>> }
export function map(pkg: Manifest) {
  const declaration = (value: string) => value.replace("./src/", "./dist/").replace(/\.tsx?$/, ".d.ts")
  const output = (value: string) => value.replace("./src/", "./dist/").replace(/\.tsx?$/, ".js")
  const exports = Object.fromEntries(
    Object.entries(pkg.exports).map(([key, value]) => {
      if (value === null) return [key, null]
      if (!/\.tsx?$/.test(value)) return [key, value]
      return [key, { import: output(value), types: declaration(value) }]
    }),
  )
  const imports = pkg.imports
    ? Object.fromEntries(
        Object.entries(pkg.imports).map(([key, conditions]) => [
          key,
          Object.fromEntries(
            Object.entries(conditions).map(([condition, value]) => [
              condition,
              condition === "types" ? declaration(value) : output(value),
            ]),
          ),
        ]),
      )
    : undefined
  return { exports, imports }
}

